export const certificates=()=>`<section class="certificates-section" id="certificates" data-certificates><div class="section container"><div class="certificates-heading"><div><p class="eyebrow">ДОКУМЕНТЫ И ГАРАНТИИ</p><h2>Сертификаты соответствия</h2><p>Документы на материалы и продукцию, которые мы используем.</p></div><div class="certificate-count"><span><strong data-cert-current>1</strong> / ${certificateFiles.length}</span></div></div><div class="certificate-gallery"><div class="certificate-track" data-cert-track tabindex="0" role="region" aria-label="Слайдер сертификатов">${certificateFiles.map((file,i)=>`<figure class="certificate-card"><a href="/assets/certificates/${file}" data-cert-open aria-haspopup="dialog" aria-controls="certificate-modal" aria-label="Открыть сертификат ${i+1} крупно"><span class="certificate-paper"><img src="/assets/certificates/${file}" width="566" height="800" loading="lazy" decoding="async" alt="Сертификат соответствия №${i+1} — документ ArtBalkon"></span><figcaption><span>СЕРТИФИКАТ</span></figcaption></a></figure>`).join('')}</div><div class="certificate-controls"><button type="button" data-cert-prev aria-label="Предыдущий сертификат">←</button><button type="button" data-cert-next aria-label="Следующий сертификат">→</button></div></div></div><dialog class="certificate-modal" id="certificate-modal" aria-labelledby="certificate-modal-title"><div class="certificate-modal-shell"><div class="certificate-modal-head"><h2 id="certificate-modal-title" aria-live="polite">Сертификат</h2><button class="comparison-close" type="button" data-cert-close aria-label="Закрыть сертификат">×</button></div><div class="certificate-modal-view"><img data-cert-image width="566" height="800" alt="Сертификат соответствия"><button class="comparison-nav certificate-modal-prev" type="button" data-cert-modal-prev aria-label="Предыдущий сертификат">‹</button><button class="comparison-nav certificate-modal-next" type="button" data-cert-modal-next aria-label="Следующий сертификат">›</button></div></div></dialog></section>`;
export function contact(context=null){
 const marker=`${context?.slug||''} ${context?.title||''} ${context?.type||''}`.toLowerCase();
 const isCombinedService=['osteklenie-balkonov','uteplenie-balkonov','otdelka-balkonov','balkon-pod-klyuch'].includes(context?.slug);
 const subject=isCombinedService
  ?{own:'свой балкон или лоджию',office:'ваш балкон или лоджию'}
  :/(?:lodzh|лоджи)/.test(marker)
  ?{own:'свою лоджию',office:'вашу лоджию'}
  :/(?:kottedzh|коттедж|загородн|дом)/.test(marker)
   ?{own:'свой дом, веранду или террасу',office:'ваш проект остекления'}
   :/(?:obedinenie|объединение)/.test(marker)
    ?{own:'своё новое пространство',office:'ваш проект объединения'}
    :context
     ?{own:'свой балкон',office:'ваш балкон'}
     :{own:'свой балкон или лоджию',office:'ваш балкон или лоджию'};
 const finalCta=`<section class="container final-section final-visual-cta" id="callback" aria-labelledby="final-cta-title"><div class="final-copy"><p class="eyebrow">ЗАМЕР И ВЫЕЗД БЕСПЛАТНО</p><h2 id="final-cta-title">Оставьте заявку<br> на замер</h2><p>Расскажите, каким хотите видеть ${subject.own}. Уточним детали, ответим на вопросы и подготовим предварительный расчёт.</p><div class="final-links"><a href="tel:${company.tel}" class="big-phone" data-event="phone_click">${company.phone}</a><a class="messenger" href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click">Написать в Telegram ${arrow}</a></div></div><form class="contact-form final-lead-form" data-lead-form="contact" novalidate><h3>Обсудим свой проект</h3><p class="final-form-intro">Оставьте контакты — перезвоним и договоримся об удобном времени замера.</p>${contactFields('contact-consent')}<p class="form-error" role="alert"></p><button class="button" type="submit">Отправить заявку ${buttonArrow}</button><p class="contact-note">Ежедневно, с 9:00 до 21:00.</p></form></section>`;
 const contactLocation=`<section class="container contact-location" id="contacts" aria-labelledby="office-title"><div class="contact-location-copy"><p class="eyebrow">ОФИС ARTBALKON</p><h2 id="office-title">Будем рады<br>встрече с вами</h2><p class="contact-location-intro">Обсудим ${subject.office}, покажем материалы и ответим на вопросы. Пожалуйста, договоритесь о встрече заранее.</p><div class="contact-location-details"><div class="contact-location-detail"><div><small>Адрес</small><p>${company.address}</p></div></div><div class="contact-location-detail"><div><small>Посещение офиса</small><p>По предварительной записи</p></div></div><div class="contact-location-detail"><div><small>Связаться с нами</small><a href="tel:${company.tel}" data-event="phone_click">${company.phone}</a></div></div></div><div class="contact-location-actions"><div class="contact-socials" aria-label="Социальные сети и мессенджеры"><a class="contact-social" href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click"><img src="/assets/telegram-logo.svg" width="128" height="128" alt="Telegram"><span>Telegram</span></a><a class="contact-social" href="${company.max}" target="_blank" rel="noopener"><img src="/assets/max-app-icon.png" width="250" height="250" alt="MAX"><span>MAX</span></a><a class="contact-social" href="${company.vk}" target="_blank" rel="noopener"><img class="contact-social-vk" src="/assets/vk-logo.svg" width="48" height="48" alt="ВКонтакте"><span>ВКонтакте</span></a></div></div></div><div class="contact-map"><iframe src="https://yandex.ru/map-widget/v1/?um=constructor%3A39574105600d7e88580935f2a3f26d12b962e6e701aa48792fcf7cf24dae4776&amp;source=constructor" width="100%" height="100%" loading="lazy" title="Офис ArtBalkon на Яндекс Картах" allowfullscreen></iframe><div class="contact-map-label"><strong>ArtBalkon</strong><span>Люберцы · офис 5</span></div></div></section>`;
 return finalCta+contactLocation;
}
export function footer(path='/'){return `<footer class="footer"><div class="container footer-grid"><div>${brand(path)}<p>Остекление, утепление и отделка<br>балконов и лоджий в Москве и Московской области.</p></div><div><p class="footer-title">Что мы делаем</p>${services.slice(0,4).map(s=>`<a href="/${s.slug}/">${s.title}</a>`).join('')}</div><div><p class="footer-title">ArtBalkon</p><a href="/#before-after">Наши работы</a><a href="/#reviews">Отзывы</a><a href="/#contacts">Контакты</a></div><div><a class="phone" href="tel:${company.tel}" data-event="phone_click">${company.phone}</a><p>${company.hours}</p><p>${company.address}<br>Посещение по предварительной записи.</p><a href="${company.telegram}" target="_blank" rel="noopener" data-event="telegram_click">Telegram ↗</a></div></div><div class="container footer-bottom"><span>© <span data-year>${new Date().getFullYear()}</span> ArtBalkon</span><a href="/privacy/">Политика конфиденциальности</a><a href="/consent/">Согласие на обработку данных</a><span>Москва и Московская область</span></div></footer>`;}
