const breadcrumbSchema=path=>{
 const segments=path.split('/').filter(Boolean),items=[{name:'Главная',url:`${company.origin}/`}];
 if(segments[0]==='nashi-raboty')items.push({name:'Наши работы',url:`${company.origin}/nashi-raboty/`});
 const service=services.find(item=>item.slug===segments[0]),project=projects.find(item=>item.slug===segments[1]);
 if(service){const parent=serviceBreadcrumbParent(service);if(parent)items.push({name:parent.title,url:`${company.origin}/${parent.slug}/`});items.push({name:service.title,url:`${company.origin}/${service.slug}/`});}
 if(project)items.push({name:project.title,url:`${company.origin}/nashi-raboty/${project.slug}/`});
 return items.length>1?{'@type':'BreadcrumbList','@id':`${company.origin}${path}#breadcrumbs`,itemListElement:items.map((item,index)=>({'@type':'ListItem',position:index+1,name:item.name,item:item.url}))}:null;
};
const structuredData=({path,title,description,image})=>{
 const canonical=`${company.origin}${path}`,imageUrl=absoluteUrl(image),businessId=`${company.origin}/#business`,websiteId=`${company.origin}/#website`;
 const graph=[
  {'@type':['HomeAndConstructionBusiness','LocalBusiness'],'@id':businessId,name:company.name,url:`${company.origin}/`,logo:{'@type':'ImageObject',url:absoluteUrl('/assets/artbalkon-logo.svg')},image:imageUrl,telephone:company.tel,email:company.privacyEmail,address:{'@type':'PostalAddress',addressLocality:'Люберцы',addressRegion:'Московская область',streetAddress:'Октябрьский проспект, 209, офис 5',addressCountry:'RU'},areaServed:[{'@type':'City',name:'Москва'},{'@type':'AdministrativeArea',name:'Московская область'}],priceRange:'₽₽',sameAs:[company.telegram,company.channel,company.max,company.vk,company.reviews,company.avito]},
  {'@type':'WebSite','@id':websiteId,url:`${company.origin}/`,name:'ArtBalkon',publisher:{'@id':businessId},inLanguage:'ru-RU'},
  {'@type':'WebPage','@id':`${canonical}#webpage`,url:canonical,name:title,description,isPartOf:{'@id':websiteId},about:{'@id':businessId},primaryImageOfPage:{'@type':'ImageObject',url:imageUrl},inLanguage:'ru-RU'}
 ];
 const crumbs=breadcrumbSchema(path);if(crumbs)graph.push(crumbs);
 const service=services.find(item=>path===`/${item.slug}/`),project=projects.find(item=>path===`/nashi-raboty/${item.slug}/`);
 if(service){const seo=serviceSeo[service.slug],price=prices[service.price];graph.push({'@type':'Service','@id':`${canonical}#service`,name:service.h1,description:seo?.metaDescription||service.offer,url:canonical,image:imageUrl,provider:{'@id':businessId},areaServed:[{'@type':'City',name:'Москва'},{'@type':'AdministrativeArea',name:'Московская область'}],...(price===null?{}:{offers:{'@type':'Offer',priceCurrency:'RUB',price:String(price),url:canonical,availability:'https://schema.org/InStock',priceSpecification:{'@type':'UnitPriceSpecification',price:String(price),priceCurrency:'RUB',unitText:'м²'}}})});if(seo?.faq?.length)graph.push({'@type':'FAQPage','@id':`${canonical}#faq`,mainEntity:seo.faq.map(([question,answer])=>({'@type':'Question',name:question,acceptedAnswer:{'@type':'Answer',text:answer}}))});}
 if(project)graph.push({'@type':'Article','@id':`${canonical}#project`,headline:project.title,description:project.intro,url:canonical,image:imageUrl,author:{'@id':businessId},publisher:{'@id':businessId},about:project.type,inLanguage:'ru-RU'});
 return {'@context':'https://schema.org','@graph':graph};
};
